#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b) {
    return a < b ? a : b;
}
int mx(int a, int b) {
    return a > b ? a : b;
}
int read(void) {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a) {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x) {
    printf("%d ", x);
}
void emitstr(int* a, int n) {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void) {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    // 起点下标 0 已可达，far 表示已经覆盖的可达前缀右端。
    int far = 0, i = 0, n = 0, ok = 0;
    n = read();
    for (i = 0; i < n; i += 1) {
        a[i] = read();
    }
    far = 0;
    for (i = 0; i < n; i += 1) {
        // 只能从可达位置扩展；不可达位置的跳跃长度不能使用。
        if (i <= far) {
            far = mx(far, (i + a[i]));
        }
    }
    ok = 0;
    // 覆盖最后下标即可成功，不要求刚好跳到最大距离。
    if (far >= (n - 1)) {
        ok = 1;
    }
    // 按平台约定返回整数 1 或 0。
    emit(ok);
    return 0;
}

